#!/usr/bin/perl
# Wraps one vkdt module so that many can be linked into a single binary. vkdt normally builds each
# module as its own shared library exporting the same function names (create_nodes, init, ...).
# We rename those per module with macros and append a table mapping the original names to the
# renamed functions, which our dlsym hands back.
#
# The table holds thunks rather than the module's functions. vkdt calls callbacks through the
# pointer types of dt_module_so_t, and some modules define them with other return types (cleanup
# returns void but is stored as dt_module_init_t, i-raw's read_source returns int). Native ABIs
# shrug that off but wasm traps on any indirect call whose signature doesn't match.
#
# usage: module_wrap.pl <module> <source as included> <source file> <output>

use strict;
use warnings;

my ($module, $include, $source, $output) = @ARGV;

# name => [return type as called, parameters, arguments]. Keep in sync with dt_module_so_t in
# src/pipe/global.h and dt_module_so_load in src/pipe/global.c.
my %api = (
  animate        => ['void', 'dt_graph_t *graph, dt_module_t *module', 'graph, module'],
  audio          => ['uint32_t', 'dt_module_t *module, uint8_t **buf, uint32_t size', 'module, buf, size'],
  bs_init        => ['int', 'void', ''],
  check_params   => ['dt_graph_run_t', 'dt_module_t *module, uint32_t parid, uint32_t num, void *oldval', 'module, parid, num, oldval'],
  cleanup        => ['int', 'dt_module_t *module', 'module'],
  commit_params  => ['void', 'dt_graph_t *graph, dt_module_t *module', 'graph, module'],
  create_nodes   => ['void', 'dt_graph_t *graph, dt_module_t *module', 'graph, module'],
  init           => ['int', 'dt_module_t *module', 'module'],
  input          => ['dt_graph_run_t', 'dt_module_t *module, dt_module_input_event_t *e', 'module, e'],
  modify_roi_in  => ['void', 'dt_graph_t *graph, dt_module_t *module', 'graph, module'],
  modify_roi_out => ['void', 'dt_graph_t *graph, dt_module_t *module', 'graph, module'],
  read_source    => ['void', 'dt_module_t *module, void *buf, dt_read_source_params_t *p', 'module, buf, p'],
  ui_callback    => ['void', 'dt_module_t *module, dt_token_t param, float arg', 'module, param, arg'],
  write_sink     => ['void', 'dt_module_t *module, void *buf, dt_write_sink_params_t *p', 'module, buf, p'],
);
my @names = sort keys %api;
(my $id = $module) =~ s/[^A-Za-z0-9_]/_/g;
my $cxx = $output =~ /\.cc$/;

# vkdt starts every function definition's name at the beginning of a line, after an optional
# return type.
open(my $in, '<', $source) or die "can't read $source: $!";
my $text = do { local $/; <$in> };
close($in);
my %defined = map { $_ => 1 } grep { my $n = $_; $text =~ /^(?:[A-Za-z_][\w \t*]*\s)?$n\s*\(/m } @names;

open(my $out, '>', $output) or die "can't write $output: $!";
print $out "// Generated by module_wrap.pl for $module. Do not edit.\n";
print $out "#define $_ wasm_${id}_$_\n" for @names;
print $out "#include \"$include\"\n";
print $out "#undef $_\n" for @names;
print $out "#include \"wasm_vkdt_modules.h\"\n";
if($cxx) {
  # Returns f(a...) as R, or a zero R when f returns void. Only a template discards the branch
  # that doesn't apply.
  print $out "#include <type_traits>\n";
  print $out "template <typename R, typename F, typename... A> static R wasm_call(F f, A... a) {\n";
  print $out "  if constexpr(std::is_void_v<std::invoke_result_t<F, A...>>) { f(a...); return R(); }\n";
  print $out "  else return (R)f(a...);\n}\n";
  print $out "extern \"C\" {\n";
}
for my $n (grep { $defined{$_} } @names) {
  my ($ret, $params, $args) = @{$api{$n}};
  my $call = "wasm_${id}_$n($args)";
  print $out "static $ret wasm_thunk_$n($params) {\n";
  if($ret eq 'void') {
    print $out "  $call;\n";
  } elsif($cxx) {
    print $out "  return wasm_call<$ret>(&wasm_${id}_$n" . ($args ? ", $args" : "") . ");\n";
  } else {
    print $out "  return ($ret)__builtin_choose_expr(\n";
    print $out "      __builtin_types_compatible_p(__typeof__($call), void), ($call, 0), $call);\n";
  }
  print $out "}\n";
}
print $out "static const wasm_vkdt_symbol_t wasm_symbols[] = {\n";
for my $n (@names) {
  print $out $defined{$n} ? "  {\"$n\", (void *)&wasm_thunk_$n},\n" : "  {\"$n\", 0},\n";
}
print $out "  {0, 0},\n};\n";
print $out "const wasm_vkdt_symbol_t *wasm_vkdt_symbols_${id}(void) { return wasm_symbols; }\n";
print $out "}\n" if $cxx;
close($out);
